{"content":"package com.persiancalendar;

import android.app.PendingIntent;
import android.appwidget.AppWidgetManager;
import android.appwidget.AppWidgetProvider;
import android.content.ComponentName;
import android.content.Context;
import android.content.Intent;
import android.widget.RemoteViews;

import java.util.Calendar;
import java.util.Locale;

/**
 * Widget provider for the Persian Calendar app.
 */
public class PersianCalendarWidgetProvider extends AppWidgetProvider {

    @Override
    public void onUpdate(Context context, AppWidgetManager appWidgetManager, int[] appWidgetIds) {
        for (int appWidgetId : appWidgetIds) {
            updateAppWidget(context, appWidgetManager, appWidgetId);
        }
    }

    @Override
    public void onReceive(Context context, Intent intent) {
        super.onReceive(context, intent);
        if (intent != null && "com.persiancalendar.WIDGET_REFRESH".equals(intent.getAction())) {
            AppWidgetManager appWidgetManager = AppWidgetManager.getInstance(context);
            int[] appWidgetIds = appWidgetManager.getAppWidgetIds(
                    new ComponentName(context, PersianCalendarWidgetProvider.class));
            onUpdate(context, appWidgetManager, appWidgetIds);
        }
    }

    private void updateAppWidget(Context context, AppWidgetManager appWidgetManager, int appWidgetId) {
        RemoteViews views = new RemoteViews(context.getPackageName(), R.layout.widget_layout);

        // Get current Persian date
        Calendar cal = Calendar.getInstance();
        int[] persianDate = PersianDateUtils.toPersian(
                cal.get(Calendar.YEAR),
                cal.get(Calendar.MONTH) + 1,
                cal.get(Calendar.DAY_OF_MONTH)
        );

        String persianMonth = PersianDateUtils.PERSIAN_MONTH_NAMES[persianDate[1] - 1];
        String dayName = PersianDateUtils.PERSIAN_WEEKDAY_NAMES[
                PersianDateUtils.persianWeekday(persianDate[0], persianDate[1], persianDate[2])
        ];

        String formattedDate = String.format(Locale.US, "%d %s %d",
                persianDate[2], persianMonth, persianDate[0]);

        views.setTextViewText(R.id.widget_date_text, formattedDate);
        views.setTextViewText(R.id.widget_day_text, dayName);

        // Click to open app
        Intent launchIntent = new Intent(context, MainActivity.class);
        PendingIntent pendingIntent = PendingIntent.getActivity(
                context, 0, launchIntent, PendingIntent.FLAG_IMMUTABLE | PendingIntent.FLAG_UPDATE_CURRENT);
        views.setOnClickPendingIntent(R.id.widget_root, pendingIntent);

        // Refresh button
        Intent refreshIntent = new Intent(context, PersianCalendarWidgetProvider.class);
        refreshIntent.setAction("com.persiancalendar.WIDGET_REFRESH");
        PendingIntent refreshPendingIntent = PendingIntent.getBroadcast(
                context, 0, refreshIntent, PendingIntent.FLAG_IMMUTABLE | PendingIntent.FLAG_UPDATE_CURRENT);
        views.setOnClickPendingIntent(R.id.widget_refresh_btn, refreshPendingIntent);

        appWidgetManager.updateAppWidget(appWidgetId, views);
    }
}","path":"/data/workspace/PersianCalendarApp/app/src/main/java/com/persiancalendar/PersianCalendarWidgetProvider.java"}
